def mutate_operators(code):
    swaps = [
        ('+', '-'), ('-', '+'), ('*', '/'), ('/', '*'),
        ('==', '!='), ('!=', '=='),
        ('<=', '<'), ('>=', '>'), ('<', '<='), ('>', '>='),
        (' and ', ' or '), (' or ', ' and '),
    ]
    results = []
    for old, new in swaps:
        if old in code:
            mutated = code.replace(old, new, 1)
            if mutated != code:
                results.append(mutated)
    return results


def mutate_off_by_one(code):
    results = []
    for match in re.finditer(r'(?<![a-zA-Z_"\'])(\d+)(?![a-zA-Z_"\'])', code):
        val = int(match.group(1))
        for delta in [1, -1]:
            new_val = val + delta
            if new_val < 0:
                continue
            mutated = code[:match.start(1)] + str(new_val) + code[match.end(1):]
            if mutated != code:
                results.append(mutated)
    return results


